#include <string>
#include <string_view>

std::string initials(std::string_view first, std::string_view last)
{
    std::string result{};
    result += first[0];
    result += '.';
    result += last[0];
    result += '.';
    return result;
}

unitTests:
TEST("Ada Lovelace") { CHECK_EQ(initials("Ada", "Lovelace"), "A.L."); }
TEST("Grace Hopper") { CHECK_EQ(initials("Grace", "Hopper"), "G.H."); }
TEST("works with std::string arguments") { std::string a{ "Linus" }, b{ "Torvalds" }; CHECK_EQ(initials(a, b), "L.T."); }

